const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centerPoint = ee.Geometry.Point(73.931617, 31.998723);
  const region = centerPoint.buffer(10000); // 10 km radius

  const startYear = 2003;
  const endYear = 2013;
  const graceCollectionId = 'JPL/GRACE/GRACE_FO_JPL_RL06_V2'; // GRACE/GRACE-FO Mascons (Liquid Water Equivalent Thickness)
  const bandName = 'lwe_thickness'; // Liquid Water Equivalent (LWE) thickness in cm
  const scale = 10000; // GRACE data has coarse resolution, typically ~200-300km. A scale of 10km (or more) is appropriate.

  // Significance threshold for groundwater decline (in cm)
  const significanceThreshold = -5.0; // A decline of 5 cm or more over the period is considered significant.

  // Helper function to get the average LWE thickness for a given year
  async function getYearlyLWE(year, geometry) {
    const collection = ee.ImageCollection(graceCollectionId)
      .filterDate(`${year}-01-01`, `${year}-12-31`)
      .filterBounds(geometry);

    const size = await collection.size().getInfo();
    if (size === 0) {
      return { value: null, numImages: 0, numPixels: 0, cloudCover: 0 };
    }

    const meanImage = collection.mean();

    // Check if the mean image is empty or has no pixels within the region
    const pixelCountDict = await meanImage.select(bandName).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const numPixels = pixelCountDict[bandName];
    if (numPixels === 0) {
      return { value: null, numImages: size, numPixels: 0, cloudCover: 0 };
    }

    const lweDict = await meanImage.select(bandName).reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const lweValue = lweDict[bandName];

    return { value: lweValue, numImages: size, numPixels: numPixels, cloudCover: 0 };
  }

  console.log(`Analyzing GRACE LWE thickness for region at ${centerPoint.coordinates().getInfo()} with a ${10000/1000}km radius.`);
  console.log(`Start Year: ${startYear}, End Year: ${endYear}`);

  // Get LWE for start year
  const lweStatsStart = await getYearlyLWE(startYear, region);
  console.log(`LWE ${startYear} Images: ${lweStatsStart.numImages}, Pixels: ${lweStatsStart.numPixels}, Val: ${lweStatsStart.value !== null ? lweStatsStart.value.toFixed(2) + ' cm' : 'N/A'}`);

  // Check for C1 (Empty Collection) or C2 (No Valid Pixels) for the start year
  if (lweStatsStart.numImages === 0) {
    console.log("C1: No GRACE images found for the start year in the specified region.");
    console.log("C1");
    return;
  }
  if (lweStatsStart.numPixels === 0) {
    console.log("C2: No valid pixels found for the start year after processing.");
    console.log("C2");
    return;
  }
  if (lweStatsStart.value === null || isNaN(lweStatsStart.value)) {
    console.log("C3: Calculation failure for start year LWE (result is None or NaN).");
    console.log("C3");
    return;
  }

  // Get LWE for end year
  const lweStatsEnd = await getYearlyLWE(endYear, region);
  console.log(`LWE ${endYear} Images: ${lweStatsEnd.numImages}, Pixels: ${lweStatsEnd.numPixels}, Val: ${lweStatsEnd.value !== null ? lweStatsEnd.value.toFixed(2) + ' cm' : 'N/A'}`);

  // Check for C1 (Empty Collection) or C2 (No Valid Pixels) for the end year
  if (lweStatsEnd.numImages === 0) {
    console.log("C1: No GRACE images found for the end year in the specified region.");
    console.log("C1");
    return;
  }
  if (lweStatsEnd.numPixels === 0) {
    console.log("C2: No valid pixels found for the end year after processing.");
    console.log("C2");
    return;
  }
  if (lweStatsEnd.value === null || isNaN(lweStatsEnd.value)) {
    console.log("C3: Calculation failure for end year LWE (result is None or NaN).");
    console.log("C3");
    return;
  }

  // Calculate the difference
  const lweDifference = lweStatsEnd.value - lweStatsStart.value;
  console.log(`Difference (${endYear} - ${startYear}): ${lweDifference.toFixed(2)} cm`);

  // 5. Validation & Final Answer
  if (lweDifference <= significanceThreshold) {
    console.log("A"); // Yes, significant decline
  } else {
    console.log("B"); // No significant decline
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
